    Connectivity is 4-directional (up, down, left, right).
    """
    if not grid:
        return 0
    rows, cols = len(grid), len(grid[0])
    visited = [[False]*cols for _ in range(rows)]
    def dfs(r,c):
        stack = [(r,c)]
        while stack:
            i,j = stack.pop()
            if visited[i][j]:
                continue
            visited[i][j] = True
            for di,dj in ((1,0),(-1,0),(0,1),(0,-1)):
